# -*- coding: utf-8 -*-
# patch_iskra_sensor_language.py
# ============================================================
# ПАТЧ: Искра — язык ДАТЧИКА, не командира.
# Спринт 45 · 2026-06-16
#
# Прошлые кодеры зашили в промт командный язык (exit_bell="звони к
# выходу", "время выходить", "если Совет в позиции"). Искра — ДАТЧИК:
# она КРИЧИТ ФАКТ ("сигнальный бар вверх/вниз"), а НЕ командует
# вход/выход. Вход и выход решают ТОЛЬКО трейдеры (A06/A07/A08):
# Авантюрист заскочит сразу, Консерватор дождётся отката — рынок рассудит.
#
# Вычищено из A01/forge/prompt.md:
#   · "звонишь в колокол выхода" / "время выходить" -> факт разворота
#   · "если Совет в позиции" -> датчик не смотрит на позиции
#   · "ещё не вход, предупреждение" -> "сигнальный бар, факт зафиксирован"
#   · exit_bell описан как ФАКТ медвежьего разворота, не приказ
#   · усилена рамка датчика в "КТО ТЫ" + запрет команд в "ЧЕГО НЕ ДЕЛАЕШЬ"
#   · входные данные синхронизированы с движком (ao.pivots, trading_state)
#
# Контракт (t1_status, exit_bell как ключи) НЕ менялся — заморожен.
# Менялся только ЯЗЫК вокруг них: состояние, а не команда.
#
# Бэкап (.bak). Запуск из корня репо: python patch_iskra_sensor_language.py
# ============================================================
import base64, os, shutil
FILES = {
    "studio/modules/trading/A01/forge/prompt.md": ""
}
def main():
    root = os.getcwd()
    print("=== ПАТЧ: Искра — язык датчика, не командира ===")
    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            shutil.copy2(path, path + ".bak")
            print(f"  [BAK] {dest}.bak")
        open(path, "wb").write(base64.b64decode(b64))
        print(f"  [OK ] {dest}")
    print("=== ГОТОВО ===")
    print("Прогони РЫНОК: Искра теперь кричит ФАКТ состояния,")
    print("а не командует вход/выход. Спроси её в чате про сигнал —")
    print("она должна говорить 'вот разворот зафиксирован', а не 'входи'.")
if __name__ == "__main__":
    main()
